1	package org.jsoup.safety;
2	
3	import org.jsoup.internal.Normalizer;
4	import org.jsoup.internal.StringUtil;
5	import org.jsoup.nodes.Attribute;
6	import org.jsoup.nodes.Element;
7	
8	import java.util.ArrayList;
9	import java.util.Collections;
10	import java.util.List;
11	import java.util.Set;
12	
13	/**
14	 Validates and rewrites {@code srcset} attributes, one image candidate at a time.
15	 <p>
16	 The attribute value is split into candidates following the HTML {@code srcset} parsing rules: a candidate consists of a
17	 URL followed by an optional width ({@code w}) or pixel density ({@code x}) descriptor. Commas only separate
18	 candidates at a candidate boundary, so commas nested inside a {@code data:} URL, a quoted value, or entity-decoded
19	 content are preserved. Each surviving URL is checked against the safelist with the same protocol and encoding rules
20	 used for ordinary URI attributes such as {@code src}; invalid descriptors cause their single candidate to be dropped,
21	 without affecting the other candidates.
22	 </p>
23	 */
24	final class SrcsetCleaner {
25	    private SrcsetCleaner() {}
26	
27	    private static final int InDescriptor = 1;
28	    private static final int InParens = 2;
29	    private static final int AfterDescriptor = 3;
30	
31	    /**
32	     Determine whether the supplied attribute is a {@code srcset} attribute that should be handled candidate by
33	     candidate, rather than treated as an ordinary opaque attribute.
34	     @param attr the attribute to test
35	     @return true if it is a {@code srcset} attribute
36	     */
37	    static boolean isSrcset(Attribute attr) {
38	        return "srcset".equalsIgnoreCase(attr.getKey());
39	    }
40	
41	    /**
42	     Clean a {@code srcset} attribute value into a value containing only the acceptable candidates, in their original
43	     order. The input element is not modified; callers must apply the result themselves.
44	     @param el the element carrying the attribute (used for URL resolution against its base URI)
45	     @param rawValue the original attribute value
46	     @param safelist the safelist to validate each candidate URL against
47	     @return the cleaning result; {@link Result#removed} is true (with a null value) when no candidate survived, in
48	     which case the attribute must be removed rather than left empty
49	     */
50	    static Result clean(Element el, String rawValue, Safelist safelist) {
51	        List<Candidate> accepted = new ArrayList<>();
52	        int dropped = 0;
53	        if (rawValue != null && !rawValue.isEmpty()) {
54	            int pos = 0;
55	            int len = rawValue.length();
56	
57	            while (pos < len) {
58	                // 1. Splitting loop: skip a run of ASCII whitespace and candidate-separating commas. Empty items,
59	                //    consecutive commas, and trailing separators are consumed here and never raise an error.
60	                while (pos < len && isWsOrComma(rawValue.charAt(pos))) pos++;
61	                if (pos >= len) break;
62	
63	                // 2. Collect the URL: a run of non-whitespace characters.
64	                int urlStart = pos;
65	                while (pos < len && !StringUtil.isWhitespace(rawValue.charAt(pos))) pos++;
66	                int urlRunEnd = pos;
67	                int urlEnd = urlRunEnd;
68	                while (urlEnd > urlStart && rawValue.charAt(urlEnd - 1) == ',') urlEnd--;
69	                String url = rawValue.substring(urlStart, urlEnd);
70	
71	                List<String> descriptors;
72	                if (urlEnd < urlRunEnd) {
73	                    // The URL run ended in comma(s) with no whitespace: the boundary has no descriptor and parsing
74	                    // restarts at the splitting loop. This is what keeps a comma inside a data: URL (e.g.
75	                    // "data:,Hello") part of the URL.
76	                    descriptors = Collections.emptyList();
77	                    pos = urlRunEnd;
78	                } else {
79	                    // 3. Tokenize the descriptors with the HTML srcset state machine, so that a comma nested in a
80	                    //    parenthesized (or quoted) descriptor does not get mistaken for a candidate boundary.
81	                    TokenizerResult tokenized = tokenizeDescriptors(rawValue, pos);
82	                    descriptors = tokenized.tokens;
83	                    pos = tokenized.nextPos;
84	                }
85	
86	                if (url.isEmpty()) continue;
87	
88	                String descriptor = parseDescriptors(descriptors);
89	                String safeUrl = (descriptor != null) ? isSafeUrl(el, url, safelist) : null;
90	                if (safeUrl != null)
91	                    accepted.add(new Candidate(safeUrl, descriptor));
92	                else
93	                    dropped++;
94	            }
95	        }
96	
97	        if (accepted.isEmpty()) return new Result(null, dropped, true);
98	        return new Result(serialize(accepted), dropped, false);
99	    }
100	
101	    /** The outcome of cleaning a srcset attribute: the rewritten {@code value} (or null) and statistics. */
102	    static final class Result {
103	        final String value;
104	        final int droppedCandidates;
105	        final boolean removed;
106	
107	        private Result(String value, int droppedCandidates, boolean removed) {
108	            this.value = value;
109	            this.droppedCandidates = droppedCandidates;
110	            this.removed = removed;
111	        }
112	    }
113	
114	    private static final class TokenizerResult {
115	        final List<String> tokens;
116	        final int nextPos; // position just past the candidate-separating comma, or at end of input
117	
118	        private TokenizerResult(List<String> tokens, int nextPos) {
119	            this.tokens = tokens;
120	            this.nextPos = nextPos;
121	        }
122	    }
123	
124	    private static boolean isWsOrComma(char c) {
125	        return c == ',' || StringUtil.isWhitespace(c);
126	    }
127	
128	    /**
129	     Run the HTML srcset descriptor tokenizer starting at the first character after the URL's whitespace run.
130	     Parenthesized content (and anything quoted within it) is taken verbatim, so commas and whitespace inside it
131	     cannot start a new candidate. Stops at a boundary comma (consumed) or end of input.
132	     */
133	    private static TokenizerResult tokenizeDescriptors(String input, int pos) {
134	        List<String> tokens = new ArrayList<>();
135	        int len = input.length();
136	        int state = InDescriptor;
137	        StringBuilder token = new StringBuilder();
138	
139	        while (pos < len) {
140	            char c = input.charAt(pos);
141	            switch (state) {
142	                case InDescriptor:
143	                    if (StringUtil.isWhitespace(c)) {
144	                        if (token.length() > 0) { tokens.add(token.toString()); token.setLength(0); }
145	                        state = AfterDescriptor;
146	                    } else if (c == ',') {
147	                        if (token.length() > 0) { tokens.add(token.toString()); token.setLength(0); }
148	                        return new TokenizerResult(tokens, pos + 1); // consume the candidate separator
149	                    } else if (c == '(') {
150	                        token.append(c);
151	                        state = InParens;
152	                    } else {
153	                        token.append(c);
154	                    }
155	                    pos++;
156	                    break;
157	                case InParens:
158	                    token.append(c); // commas, whitespace, and quotes in here are all literal
159	                    if (c == ')') state = InDescriptor;
160	                    pos++;
161	                    break;
162	                case AfterDescriptor:
163	                    if (StringUtil.isWhitespace(c)) {
164	                        pos++;
165	                    } else if (c == ',') {
166	                        return new TokenizerResult(tokens, pos + 1);
167	                    } else {
168	                        state = InDescriptor; // reprocess this character as a new token
169	                    }
170	                    break;
171	            }
172	        }
173	        if (token.length() > 0) tokens.add(token.toString());
174	        return new TokenizerResult(tokens, pos);
175	    }
176	
177	    /**
178	     Validate the tokenized descriptor list of one candidate. Legal forms are: no descriptor, a single non-zero
179	     width ({@code <integer>w}), or a single finite non-negative pixel density ({@code <number>x}). Duplicated,
180	     unknown, parenthesized, or syntactically invalid descriptors invalidate the candidate.
181	     @return the normalized descriptor suffix ({@code ""} when absent, or {@code " <descriptor>"}), or {@code null}
182	     */
183	    private static String parseDescriptors(List<String> tokens) {
184	        if (tokens.isEmpty()) return "";
185	        if (tokens.size() > 1) return null;
186	
187	        String descriptor = tokens.get(0);
188	        if (descriptor.isEmpty()) return "";
189	        char suffix = descriptor.charAt(descriptor.length() - 1);
190	        if (suffix != 'w' && suffix != 'x') return null; // only lower-case width/density descriptors are valid
191	        String number = descriptor.substring(0, descriptor.length() - 1);
192	        if (number.isEmpty()) return null;
193	
194	        if (suffix == 'w') {
195	            if (parseWidth(number) == null) return null;
196	        } else {
197	            if (parseDensity(number) == null) return null;
198	        }
199	        return " " + descriptor;
200	    }
201	
202	    /** Parse a non-negative integer with no sign, exponent, or decimal point; zero and overflow are invalid. */
203	    private static Long parseWidth(String s) {
204	        long value = 0;
205	        for (int i = 0; i < s.length(); i++) {
206	            char c = s.charAt(i);
207	            if (c < '0' || c > '9') return null;
208	            int digit = c - '0';
209	            if (value > (Long.MAX_VALUE - digit) / 10) return null; // overflow
210	            value = value * 10 + digit;
211	        }
212	        return value == 0L ? null : value;
213	    }
214	
215	    /** Parse a finite non-negative floating-point number matching the HTML valid floating-point number grammar. */
216	    private static Double parseDensity(String s) {
217	        int i = 0;
218	        if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
219	            if (s.charAt(i) == '-') return null;
220	            i++;
221	        }
222	        int intDigits = 0;
223	        while (i < s.length() && isAsciiDigit(s.charAt(i))) { intDigits++; i++; }
224	        int fracDigits = 0;
225	        if (i < s.length() && s.charAt(i) == '.') {
226	            i++;
227	            while (i < s.length() && isAsciiDigit(s.charAt(i))) { fracDigits++; i++; }
228	        }
229	        // grammar: digits before the optional dot, or digits after it (".5"); a lone "." is invalid
230	        if (intDigits == 0 && fracDigits == 0) return null;
231	        if (i < s.length() && (s.charAt(i) == 'e' || s.charAt(i) == 'E')) {
232	            i++;
233	            if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) i++;
234	            int exponentDigits = 0;
235	            while (i < s.length() && isAsciiDigit(s.charAt(i))) { exponentDigits++; i++; }
236	            if (exponentDigits == 0) return null;
237	        }
238	        if (i != s.length()) return null; // trailing junk
239	        try {
240	            double value = Double.parseDouble(s);
241	            // the HTML spec only rejects negative densities here; zero is a grammatical, if odd, density
242	            if (value < 0d || Double.isNaN(value) || Double.isInfinite(value)) return null;
243	            return value;
244	        } catch (NumberFormatException e) {
245	            return null;
246	        }
247	    }
248	
249	    private static boolean isAsciiDigit(char c) {
250	        return c >= '0' && c <= '9';
251	    }
252	
253	    /**
254	     Check one candidate URL against the safelist's protocol policy and return the URL spelling to emit.
255	     <p>
256	     This mirrors the ordinary URI attribute path in {@link Safelist}: the URL is resolved against the element's base
257	     URI (which strips and percent-normalizes control characters the same way {@code src} does), and the resolved or
258	     as-written value must begin with an allowed scheme. When relative links are not preserved, resolvable candidates
259	     are emitted in absolute form, exactly like an ordinary {@code src} value.
260	     </p>
261	     @return the URL to keep (absolute or original spelling), or {@code null} if it must be dropped
262	     */
263	    private static String isSafeUrl(Element el, String url, Safelist safelist) {
264	        Set<Safelist.Protocol> protocols = safelist.srcsetProtocols(el.normalName());
265	        if (protocols.isEmpty()) return stripControlChars(url); // no protocol policy: accept, like an ordinary untyped attribute
266	
267	        String resolved = StringUtil.resolve(el.baseUri(), url);
268	        String check = resolved;
269	        if (check.isEmpty() && !StringUtil.hasHttpScheme(url)) check = url; // custom schemes checked as written
270	        check = stripControlChars(check);
271	        if (check.isEmpty()) return null; // an unresolvable relative URL with no base is not acceptable
272	
273	        String lc = Normalizer.lowerCase(check);
274	        for (Safelist.Protocol protocol : protocols) {
275	            String prot = protocol.toString();
276	            if (prot.equals("#")) continue; // fragment anchors are not image candidates
277	            if (lc.startsWith(prot)
278	                && lc.length() > prot.length()
279	                && lc.charAt(prot.length()) == ':') {
280	                // Emit the absolute form like an ordinary src value, unless relative links are preserved; in either
281	                // case strip ASCII control characters, which browsers remove from URLs and would destabilize reparse.
282	                String emit = (!safelist.preserveRelativeLinks() && !resolved.isEmpty()) ? resolved : url;
283	                return stripControlChars(emit);
284	            }
285	        }
286	        return null;
287	    }
288	
289	    private static String stripControlChars(String url) {
290	        StringBuilder sb = null;
291	        for (int i = 0; i < url.length(); i++) {
292	            char c = url.charAt(i);
293	            if (c <= 0x1f) {
294	                if (sb == null) {
295	                    sb = new StringBuilder(url.length());
296	                    sb.append(url, 0, i);
297	                }
298	            } else if (sb != null) {
299	                sb.append(c);
300	            }
301	        }
302	        return sb == null ? url : sb.toString();
303	    }
304	
305	    private static String serialize(List<Candidate> candidates) {
306	        StringBuilder sb = StringUtil.borrowBuilder();
307	        for (int i = 0; i < candidates.size(); i++) {
308	            if (i > 0) sb.append(", ");
309	            Candidate candidate = candidates.get(i);
310	            sb.append(candidate.url).append(candidate.descriptor);
311	        }
312	        return StringUtil.releaseBuilder(sb);
313	    }
314	
315	    private static final class Candidate {
316	        final String url;
317	        final String descriptor; // normalized as "" or " <descriptor>"
318	
319	        Candidate(String url, String descriptor) {
320	            this.url = url;
321	            this.descriptor = descriptor;
322	        }
323	    }
324	}
