            .addProtocols(":all", "src", "http", "https");
        String clean = Jsoup.clean("<img srcset=\"http://example.com/a.jpg 1x, javascript:alert(1)\">", "http://example.com/", safelist);
        assertEquals("<img srcset=\"http://example.com/a.jpg 1x\">", clean);
